87	DefaultBtInteractive::DefaultBtInteractive(
88	    const std::shared_ptr<DownloadContext>& downloadContext,
89	    const std::shared_ptr<Peer>& peer)
90	    : cuid_(0),
91	      downloadContext_(downloadContext),
92	      peer_(peer),
93	      metadataGetMode_(false),
94	      localNode_(nullptr),
95	      lastHaveIndex_(0),
96	      allowedFastSetSize_(10),
97	      keepAliveTimer_(global::wallclock()),
98	      floodingTimer_(global::wallclock()),
99	      inactiveTimer_(global::wallclock()),
100	      pexTimer_(global::wallclock()),
101	      perSecTimer_(global::wallclock()),
102	      keepAliveInterval_(120),
103	      utPexEnabled_(false),
104	      dhtEnabled_(false),
105	      numReceivedMessage_(0),
106	      maxOutstandingRequest_(DEFAULT_MAX_OUTSTANDING_REQUEST),
107	      requestGroupMan_(nullptr),
108	      tcpPort_(0)
109	{
110	}
