172	void DefaultBtInteractive::doPostHandshakeProcessing()
173	{
174	  // Set time 0 to haveTimer to cache http/ftp download piece completion
175	  keepAliveTimer_ = global::wallclock();
176	  floodingTimer_ = global::wallclock();
177	  pexTimer_ = Timer::zero();
178	  if (peer_->isExtendedMessagingEnabled()) {
179	    addHandshakeExtendedMessageToQueue();
180	  }
181	  if (!metadataGetMode_) {
182	    addBitfieldMessageToQueue();
183	  }
184	  if (peer_->isDHTEnabled() && dhtEnabled_) {
185	    addPortMessageToQueue();
186	  }
187	  if (!metadataGetMode_) {
188	    addAllowedFastMessageToQueue();
189	  }
190	  sendPendingMessage();
191	}
192	
193	void DefaultBtInteractive::addPortMessageToQueue()
194	{
195	  dispatcher_->addMessageToQueue(
196	      messageFactory_->createPortMessage(localNode_->getPort()));
197	}
198	
199	void DefaultBtInteractive::addHandshakeExtendedMessageToQueue()
200	{
201	  auto m = make_unique<HandshakeExtensionMessage>();
202	  m->setClientVersion(bittorrent::getStaticPeerAgent());
203	  m->setTCPPort(tcpPort_);
204	  m->setExtensions(extensionMessageRegistry_->getExtensions());
205	  auto attrs = bittorrent::getTorrentAttrs(downloadContext_);
206	  if (!attrs->metadata.empty()) {
207	    m->setMetadataSize(attrs->metadataSize);
208	  }
209	  dispatcher_->addMessageToQueue(
210	      messageFactory_->createBtExtendedMessage(std::move(m)));
211	}
212	
213	void DefaultBtInteractive::addBitfieldMessageToQueue()
214	{
215	  if (peer_->isFastExtensionEnabled()) {
216	    if (pieceStorage_->allDownloadFinished()) {
217	      dispatcher_->addMessageToQueue(messageFactory_->createHaveAllMessage());
218	    }
219	    else if (pieceStorage_->getCompletedLength() > 0) {
220	      dispatcher_->addMessageToQueue(messageFactory_->createBitfieldMessage());
221	    }
222	    else {
223	      dispatcher_->addMessageToQueue(messageFactory_->createHaveNoneMessage());
224	    }
225	  }
226	  else {
227	    if (pieceStorage_->getCompletedLength() > 0) {
228	      dispatcher_->addMessageToQueue(messageFactory_->createBitfieldMessage());
229	    }
230	  }
231	}
232	
233	void DefaultBtInteractive::addAllowedFastMessageToQueue()
234	{
235	  if (peer_->isFastExtensionEnabled()) {
236	    auto fastSet = bittorrent::computeFastSet(
237	        peer_->getIPAddress(), downloadContext_->getNumPieces(),
238	        bittorrent::getInfoHash(downloadContext_), allowedFastSetSize_);
239	    for (std::vector<size_t>::const_iterator itr = fastSet.begin(),
240	                                             eoi = fastSet.end();
241	         itr != eoi; ++itr) {
242	      dispatcher_->addMessageToQueue(
243	          messageFactory_->createAllowedFastMessage(*itr));
244	    }
245	  }
246	}
247	
248	void DefaultBtInteractive::decideChoking()
249	{
250	  if (peer_->shouldBeChoking()) {
251	    if (!peer_->amChoking()) {
252	      peer_->amChoking(true);
253	      dispatcher_->doChokingAction();
254	      dispatcher_->addMessageToQueue(messageFactory_->createChokeMessage());
255	    }
256	  }
257	  else {
258	    if (peer_->amChoking()) {
259	      peer_->amChoking(false);
260	      dispatcher_->addMessageToQueue(messageFactory_->createUnchokeMessage());
261	    }
262	  }
263	}
264	
265	void DefaultBtInteractive::checkHave()
266	{
267	  std::vector<size_t> haveIndexes;
268	
269	  lastHaveIndex_ = pieceStorage_->getAdvertisedPieceIndexes(haveIndexes, cuid_,
270	                                                            lastHaveIndex_);
271	
272	  // Use bitfield message if it is equal to or less than the total
273	  // size of have messages.
274	  if (5 + pieceStorage_->getBitfieldLength() <= haveIndexes.size() * 9) {
275	    if (peer_->isFastExtensionEnabled() &&
276	        pieceStorage_->allDownloadFinished()) {
277	      dispatcher_->addMessageToQueue(messageFactory_->createHaveAllMessage());
278	
279	      return;
280	    }
281	
282	    dispatcher_->addMessageToQueue(messageFactory_->createBitfieldMessage());
283	
284	    return;
285	  }
286	
287	  for (auto idx : haveIndexes) {
288	    dispatcher_->addMessageToQueue(messageFactory_->createHaveMessage(idx));
289	  }
290	}
291	
292	void DefaultBtInteractive::sendKeepAlive()
293	{
294	  if (keepAliveTimer_.difference(global::wallclock()) >= keepAliveInterval_) {
295	    dispatcher_->addMessageToQueue(messageFactory_->createKeepAliveMessage());
296	    dispatcher_->sendMessages();
297	    keepAliveTimer_ = global::wallclock();
298	  }
299	}
300	
301	size_t DefaultBtInteractive::receiveMessages()
302	{
303	  size_t countOldOutstandingRequest = dispatcher_->countOutstandingRequest();
304	  size_t msgcount = 0;
305	  while (1) {
306	    if (requestGroupMan_->doesOverallDownloadSpeedExceed() ||
307	        downloadContext_->getOwnerRequestGroup()->doesDownloadSpeedExceed()) {
308	      break;
309	    }
310	    auto message = btMessageReceiver_->receiveMessage();
311	    if (!message) {
312	      break;
313	    }
314	    ++msgcount;
315	    A2_LOG_INFO(fmt(MSG_RECEIVE_PEER_MESSAGE, cuid_,
316	                    peer_->getIPAddress().c_str(), peer_->getPort(),
317	                    message->toString().c_str()));
318	    message->doReceivedAction();
319	
320	    switch (message->getId()) {
321	    case BtChokeMessage::ID:
322	      if (!peer_->peerChoking()) {
323	        floodingStat_.incChokeUnchokeCount();
324	      }
325	      break;
326	    case BtUnchokeMessage::ID:
327	      if (peer_->peerChoking()) {
328	        floodingStat_.incChokeUnchokeCount();
329	      }
330	      break;
331	    case BtRequestMessage::ID:
332	    case BtPieceMessage::ID:
333	      inactiveTimer_ = global::wallclock();
334	      break;
335	    case BtKeepAliveMessage::ID:
336	      floodingStat_.incKeepAliveCount();
337	      break;
338	    }
339	  }
340	
341	  if (!pieceStorage_->isEndGame() &&
342	      countOldOutstandingRequest > dispatcher_->countOutstandingRequest() &&
343	      (countOldOutstandingRequest - dispatcher_->countOutstandingRequest()) *
344	              4 >=
345	          maxOutstandingRequest_) {
346	    maxOutstandingRequest_ = std::min((size_t)UB_MAX_OUTSTANDING_REQUEST,
347	                                      maxOutstandingRequest_ * 2);
348	  }
349	  return msgcount;
350	}
351	
352	void DefaultBtInteractive::decideInterest()
353	{
354	  if (pieceStorage_->hasMissingPiece(peer_)) {
355	    if (!peer_->amInterested()) {
356	      A2_LOG_DEBUG(fmt(MSG_PEER_INTERESTED, cuid_));
357	      peer_->amInterested(true);
358	      dispatcher_->addMessageToQueue(
359	          messageFactory_->createInterestedMessage());
360	    }
361	  }
362	  else {
363	    if (peer_->amInterested()) {
364	      A2_LOG_DEBUG(fmt(MSG_PEER_NOT_INTERESTED, cuid_));
365	      peer_->amInterested(false);
366	      dispatcher_->addMessageToQueue(
367	          messageFactory_->createNotInterestedMessage());
368	    }
369	  }
370	}
371	
372	void DefaultBtInteractive::fillPiece(size_t maxMissingBlock)
373	{
374	  if (pieceStorage_->hasMissingPiece(peer_)) {
375	    size_t numMissingBlock = btRequestFactory_->countMissingBlock();
376	    if (numMissingBlock >= maxMissingBlock) {
377	      return;
378	    }
379	    size_t diffMissingBlock = maxMissingBlock - numMissingBlock;
380	    std::vector<std::shared_ptr<Piece>> pieces;
381	    if (peer_->peerChoking()) {
382	      if (peer_->isFastExtensionEnabled()) {
383	        if (pieceStorage_->isEndGame()) {
384	          pieceStorage_->getMissingFastPiece(
385	              pieces, diffMissingBlock, peer_,
386	              btRequestFactory_->getTargetPieceIndexes(), cuid_);
387	        }
388	        else {
389	          pieces.reserve(diffMissingBlock);
390	          pieceStorage_->getMissingFastPiece(pieces, diffMissingBlock, peer_,
391	                                             cuid_);
392	        }
393	      }
394	    }
395	    else {
396	      if (pieceStorage_->isEndGame()) {
397	        pieceStorage_->getMissingPiece(
398	            pieces, diffMissingBlock, peer_,
399	            btRequestFactory_->getTargetPieceIndexes(), cuid_);
400	      }
401	      else {
402	        pieces.reserve(diffMissingBlock);
403	        pieceStorage_->getMissingPiece(pieces, diffMissingBlock, peer_, cuid_);
404	      }
405	    }
406	    for (std::vector<std::shared_ptr<Piece>>::const_iterator i = pieces.begin(),
407	                                                             eoi = pieces.end();
408	         i != eoi; ++i) {
409	      btRequestFactory_->addTargetPiece(*i);
410	    }
411	  }
412	}
413	
414	void DefaultBtInteractive::addRequests()
415	{
416	  if (!pieceStorage_->isEndGame() && !pieceStorage_->hasMissingUnusedPiece()) {
417	    pieceStorage_->enterEndGame();
418	  }
419	  fillPiece(maxOutstandingRequest_);
420	  size_t reqNumToCreate =
421	      maxOutstandingRequest_ <= dispatcher_->countOutstandingRequest()
422	          ? 0
423	          : maxOutstandingRequest_ - dispatcher_->countOutstandingRequest();
424	
425	  if (reqNumToCreate > 0) {
426	    auto requests = btRequestFactory_->createRequestMessages(
427	        reqNumToCreate, pieceStorage_->isEndGame());
428	    for (auto& i : requests) {
429	      dispatcher_->addMessageToQueue(std::move(i));
430	    }
431	  }
432	}
433	
434	void DefaultBtInteractive::cancelAllPiece()
435	{
436	  btRequestFactory_->removeAllTargetPiece();
437	  if (metadataGetMode_ && downloadContext_->getTotalLength() > 0) {
438	    std::vector<size_t> metadataRequests =
439	        utMetadataRequestTracker_->getAllTrackedIndex();
440	    for (std::vector<size_t>::const_iterator i = metadataRequests.begin(),
441	                                             eoi = metadataRequests.end();
442	         i != eoi; ++i) {
443	      A2_LOG_DEBUG(
444	          fmt("Cancel metadata: piece=%lu", static_cast<unsigned long>(*i)));
445	      pieceStorage_->cancelPiece(pieceStorage_->getPiece(*i), cuid_);
446	    }
447	  }
448	}
449	
450	void DefaultBtInteractive::sendPendingMessage() { dispatcher_->sendMessages(); }
451	
452	namespace {
453	constexpr auto FLOODING_CHECK_INTERVAL = 5_s;
454	} // namespace
455	
456	void DefaultBtInteractive::detectMessageFlooding()
457	{
458	  if (floodingTimer_.difference(global::wallclock()) >=
459	      FLOODING_CHECK_INTERVAL) {
460	    if (floodingStat_.getChokeUnchokeCount() >= 2 ||
461	        floodingStat_.getKeepAliveCount() >= 2) {
462	      throw DL_ABORT_EX(EX_FLOODING_DETECTED);
463	    }
464	    else {
465	      floodingStat_.reset();
466	    }
467	    floodingTimer_ = global::wallclock();
468	  }
469	}
470	
471	void DefaultBtInteractive::checkActiveInteraction()
472	{
473	  auto inactiveTime = inactiveTimer_.difference(global::wallclock());
474	  // To allow aria2 to accept mutially interested peer, disconnect uninterested
475	  // peer.
476	  {
477	    const time_t interval = 30;
478	    if (!peer_->amInterested() && !peer_->peerInterested() &&
479	        inactiveTime >= std::chrono::seconds(interval)) {
480	      peer_->setDisconnectedGracefully(true);
481	      // TODO change the message
482	      throw DL_ABORT_EX(
483	          fmt("Disconnect peer because we are not interested each other"
484	              " after %ld second(s).",
485	              static_cast<long int>(interval)));
486	    }
487	  }
488	  // Since the peers which are *just* connected and do nothing to improve
489	  // mutual download progress are completely waste of resources, those peers
490	  // are disconnected in a certain time period.
491	  {
492	    const time_t interval = 60;
493	    if (inactiveTime >= std::chrono::seconds(interval)) {
494	      peer_->setDisconnectedGracefully(true);
495	      throw DL_ABORT_EX(
496	          fmt(EX_DROP_INACTIVE_CONNECTION, static_cast<long int>(interval)));
497	    }
498	  }
499	  // If both of us are seeders, drop connection.
500	  if (peer_->isSeeder() && pieceStorage_->downloadFinished()) {
501	    throw DL_ABORT_EX(MSG_GOOD_BYE_SEEDER);
502	  }
503	}
504	
505	void DefaultBtInteractive::addPeerExchangeMessage()
506	{
507	  if (pexTimer_.difference(global::wallclock()) >=
508	      UTPexExtensionMessage::DEFAULT_INTERVAL) {
509	    auto m = make_unique<UTPexExtensionMessage>(
510	        peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_PEX));
511	    auto& usedPeers = peerStorage_->getUsedPeers();
512	    for (auto i = std::begin(usedPeers), eoi = std::end(usedPeers);
513	         i != eoi && !m->freshPeersAreFull(); ++i) {
514	      if ((*i)->isActive() && peer_->getIPAddress() != (*i)->getIPAddress()) {
515	        m->addFreshPeer(*i);
516	      }
517	    }
518	    auto& droppedPeers = peerStorage_->getDroppedPeers();
519	    for (auto i = std::begin(droppedPeers), eoi = std::end(droppedPeers);
520	         i != eoi && !m->droppedPeersAreFull(); ++i) {
521	      if (peer_->getIPAddress() != (*i)->getIPAddress()) {
522	        m->addDroppedPeer(*i);
523	      }
524	    }
525	    dispatcher_->addMessageToQueue(
526	        messageFactory_->createBtExtendedMessage(std::move(m)));
527	    pexTimer_ = global::wallclock();
528	  }
529	}
530	
531	void DefaultBtInteractive::doInteractionProcessing()
532	{
533	  if (metadataGetMode_) {
534	    sendKeepAlive();
535	    numReceivedMessage_ = receiveMessages();
536	    // PieceStorage is re-initialized with metadata_size in
537	    // HandshakeExtensionMessage::doReceivedAction().
538	    pieceStorage_ = downloadContext_->getOwnerRequestGroup()->getPieceStorage();
539	    if (peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_METADATA) &&
540	        downloadContext_->getTotalLength() > 0) {
541	      size_t num = utMetadataRequestTracker_->avail();
542	      if (num > 0) {
543	        auto requests =
544	            utMetadataRequestFactory_->create(num, pieceStorage_.get());
545	        for (auto& i : requests) {
546	          dispatcher_->addMessageToQueue(std::move(i));
547	        }
548	      }
549	      if (perSecTimer_.difference(global::wallclock()) >= 1_s) {
550	        perSecTimer_ = global::wallclock();
551	        // Drop timeout request after queuing message to give a chance
552	        // to other connection to request piece.
553	        auto indexes = utMetadataRequestTracker_->removeTimeoutEntry();
554	        for (auto idx : indexes) {
555	          pieceStorage_->cancelPiece(pieceStorage_->getPiece(idx), cuid_);
556	        }
557	      }
558	      if (pieceStorage_->downloadFinished()) {
559	        downloadContext_->getOwnerRequestGroup()->setForceHaltRequested(
560	            true, RequestGroup::NONE);
561	      }
562	    }
563	  }
564	  else {
565	    checkActiveInteraction();
566	    if (perSecTimer_.difference(global::wallclock()) >= 1_s) {
567	      perSecTimer_ = global::wallclock();
568	      dispatcher_->checkRequestSlotAndDoNecessaryThing();
569	    }
570	    numReceivedMessage_ = receiveMessages();
571	    detectMessageFlooding();
572	    decideChoking();
573	    decideInterest();
574	    checkHave();
575	    sendKeepAlive();
576	    btRequestFactory_->removeCompletedPiece();
577	    if (!pieceStorage_->downloadFinished()) {
578	      addRequests();
579	    }
580	  }
581	  if (peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_PEX) &&
582	      utPexEnabled_) {
583	    addPeerExchangeMessage();
584	  }
585	
