114	void DefaultBtInteractive::initiateHandshake()
115	{
116	  dispatcher_->addMessageToQueue(messageFactory_->createHandshakeMessage(
117	      bittorrent::getInfoHash(downloadContext_),
118	      bittorrent::getStaticPeerId()));
