122	std::unique_ptr<BtHandshakeMessage>
123	DefaultBtInteractive::receiveHandshake(bool quickReply)
124	{
125	  auto message = btMessageReceiver_->receiveHandshake(quickReply);
126	  if (!message) {
127	    return nullptr;
128	  }
129	  if (memcmp(message->getPeerId(), bittorrent::getStaticPeerId(),
130	             PEER_ID_LENGTH) == 0) {
131	    throw DL_ABORT_EX(
132	        fmt("CUID#%" PRId64 " - Drop connection from the same Peer ID", cuid_));
133	  }
134	  for (auto& peer : peerStorage_->getUsedPeers()) {
135	    if (peer->isActive() &&
136	        memcmp(peer->getPeerId(), message->getPeerId(), PEER_ID_LENGTH) == 0) {
137	      throw DL_ABORT_EX(
138	          fmt("CUID#%" PRId64 " - Same Peer ID has been already seen.", cuid_));
139	    }
140	  }
141	
142	  peer_->setPeerId(message->getPeerId());
143	
144	  if (message->isFastExtensionSupported()) {
145	    peer_->setFastExtensionEnabled(true);
146	    A2_LOG_INFO(fmt(MSG_FAST_EXTENSION_ENABLED, cuid_));
147	  }
148	  if (message->isExtendedMessagingEnabled()) {
149	    peer_->setExtendedMessagingEnabled(true);
150	    if (!utPexEnabled_) {
151	      extensionMessageRegistry_->removeExtension(
152	          ExtensionMessageRegistry::UT_PEX);
153	    }
154	    A2_LOG_INFO(fmt(MSG_EXTENDED_MESSAGING_ENABLED, cuid_));
155	  }
156	  if (message->isDHTEnabled()) {
157	    peer_->setDHTEnabled(true);
158	    A2_LOG_INFO(fmt(MSG_DHT_ENABLED_PEER, cuid_));
159	  }
160	  A2_LOG_INFO(fmt(MSG_RECEIVE_PEER_MESSAGE, cuid_,
161	                  peer_->getIPAddress().c_str(), peer_->getPort(),
162	                  message->toString().c_str()));
163	  return message;
164	}
