175	  keepAliveTimer_ = global::wallclock();
176	  floodingTimer_ = global::wallclock();
177	  pexTimer_ = Timer::zero();
178	  if (peer_->isExtendedMessagingEnabled()) {
179	    addHandshakeExtendedMessageToQueue();
180	  }
181	  if (!metadataGetMode_) {
182	    addBitfieldMessageToQueue();
183	  }
184	  if (peer_->isDHTEnabled() && dhtEnabled_) {
185	    addPortMessageToQueue();
186	  }
187	  if (!metadataGetMode_) {
