83	PeerInteractionCommand::PeerInteractionCommand(
84	    cuid_t cuid, RequestGroup* requestGroup, const std::shared_ptr<Peer>& p,
85	    DownloadEngine* e, const std::shared_ptr<BtRuntime>& btRuntime,
86	    const std::shared_ptr<PieceStorage>& pieceStorage,
87	    const std::shared_ptr<PeerStorage>& peerStorage,
88	    const std::shared_ptr<SocketCore>& s, Seq sequence,
89	    std::unique_ptr<PeerConnection> peerConnection)
90	    : PeerAbstractCommand{cuid, p, e, s},
91	      requestGroup_{requestGroup},
92	      btRuntime_{btRuntime},
93	      pieceStorage_{pieceStorage},
94	      peerStorage_{peerStorage},
95	      sequence_{sequence}
96	{
97	  // TODO move following bunch of processing to separate method, like init()
98	  if (sequence_ == INITIATOR_SEND_HANDSHAKE) {
99	    disableReadCheckSocket();
100	    setWriteCheckSocket(getSocket());
101	    setTimeout(std::chrono::seconds(
102	        getOption()->getAsInt(PREF_PEER_CONNECTION_TIMEOUT)));
103	  }
104	
105	  int family;
106	  unsigned char compact[COMPACT_LEN_IPV6];
107	  int compactlen = bittorrent::packcompact(compact, getPeer()->getIPAddress(),
108	                                           getPeer()->getPort());
109	  if (compactlen == COMPACT_LEN_IPV6) {
110	    family = AF_INET6;
111	  }
112	  else {
113	    family = AF_INET;
114	  }
115	
116	  auto torrentAttrs =
117	      bittorrent::getTorrentAttrs(requestGroup_->getDownloadContext());
118	  bool metadataGetMode = torrentAttrs->metadata.empty();
119	
120	  auto exMsgRegistry = make_unique<ExtensionMessageRegistry>();
121	  exMsgRegistry->setExtensionMessageID(ExtensionMessageRegistry::UT_PEX, 8);
122	  // http://www.bittorrent.org/beps/bep_0009.html
123	  exMsgRegistry->setExtensionMessageID(ExtensionMessageRegistry::UT_METADATA,
124	                                       9);
125	
126	  auto extensionMessageFactory = make_unique<DefaultExtensionMessageFactory>(
127	      getPeer(), exMsgRegistry.get());
128	  auto extensionMessageFactoryPtr = extensionMessageFactory.get();
129	  extensionMessageFactory->setPeerStorage(peerStorage.get());
130	  extensionMessageFactory->setDownloadContext(
131	      requestGroup_->getDownloadContext().get());
132	  // PieceStorage will be set later.
133	
134	  auto factory = make_unique<DefaultBtMessageFactory>();
135	  auto factoryPtr = factory.get();
136	  factory->setCuid(cuid);
137	  factory->setDownloadContext(requestGroup_->getDownloadContext().get());
138	  factory->setPieceStorage(pieceStorage.get());
139	  factory->setPeerStorage(peerStorage.get());
140	  factory->setExtensionMessageFactory(extensionMessageFactory.get());
141	  factory->setPeer(getPeer());
142	  if (family == AF_INET) {
143	    factory->setLocalNode(DHTRegistry::getData().localNode.get());
144	    factory->setRoutingTable(DHTRegistry::getData().routingTable.get());
145	    factory->setTaskQueue(DHTRegistry::getData().taskQueue.get());
146	    factory->setTaskFactory(DHTRegistry::getData().taskFactory.get());
147	  }
148	  else {
149	    factory->setLocalNode(DHTRegistry::getData6().localNode.get());
150	    factory->setRoutingTable(DHTRegistry::getData6().routingTable.get());
151	    factory->setTaskQueue(DHTRegistry::getData6().taskQueue.get());
152	    factory->setTaskFactory(DHTRegistry::getData6().taskFactory.get());
153	  }
154	  if (metadataGetMode) {
155	    factory->enableMetadataGetMode();
156	  }
157	
158	  if (!peerConnection) {
159	    peerConnection = make_unique<PeerConnection>(cuid, getPeer(), getSocket());
160	  }
161	  else {
162	    if (sequence_ == RECEIVER_WAIT_HANDSHAKE &&
163	        peerConnection->getBufferLength() > 0) {
164	      setStatus(Command::STATUS_ONESHOT_REALTIME);
165	      getDownloadEngine()->setNoWait(true);
166	    }
167	  }
168	  // If the number of pieces gets bigger, the length of Bitfield
169	  // message payload exceeds the initial buffer capacity of
170	  // PeerConnection, which is MAX_PAYLOAD_LEN.  We expand buffer as
171	  // necessary so that PeerConnection can receive the Bitfield
172	  // message.
173	  size_t bitfieldPayloadSize =
174	      1 + (requestGroup_->getDownloadContext()->getNumPieces() + 7) / 8;
175	  peerConnection->reserveBuffer(bitfieldPayloadSize);
176	
177	  auto dispatcher = make_unique<DefaultBtMessageDispatcher>();
178	  auto dispatcherPtr = dispatcher.get();
179	  dispatcher->setCuid(cuid);
180	  dispatcher->setPeer(getPeer());
181	  dispatcher->setDownloadContext(requestGroup_->getDownloadContext().get());
182	  dispatcher->setRequestTimeout(
183	      std::chrono::seconds(getOption()->getAsInt(PREF_BT_REQUEST_TIMEOUT)));
184	  dispatcher->setBtMessageFactory(factory.get());
185	  dispatcher->setRequestGroupMan(
186	      getDownloadEngine()->getRequestGroupMan().get());
187	  dispatcher->setPeerConnection(peerConnection.get());
188	
189	  auto receiver = make_unique<DefaultBtMessageReceiver>();
190	  receiver->setDownloadContext(requestGroup_->getDownloadContext().get());
191	  receiver->setPeerConnection(peerConnection.get());
192	  receiver->setDispatcher(dispatcher.get());
193	  receiver->setBtMessageFactory(factory.get());
194	
195	  auto reqFactory = make_unique<DefaultBtRequestFactory>();
196	  reqFactory->setPeer(getPeer());
197	  reqFactory->setPieceStorage(pieceStorage.get());
198	  reqFactory->setBtMessageDispatcher(dispatcher.get());
199	  reqFactory->setBtMessageFactory(factory.get());
200	  reqFactory->setCuid(cuid);
201	
202	  // reverse depends
203	  factory->setBtMessageDispatcher(dispatcher.get());
204	  factory->setBtRequestFactory(reqFactory.get());
205	  factory->setPeerConnection(peerConnection.get());
206	
207	  extensionMessageFactory->setBtMessageDispatcher(dispatcher.get());
208	  extensionMessageFactory->setBtMessageFactory(factory.get());
209	
210	  getPeer()->allocateSessionResource(
211	      requestGroup_->getDownloadContext()->getPieceLength(),
212	      requestGroup_->getDownloadContext()->getTotalLength());
213	  getPeer()->setBtMessageDispatcher(dispatcher.get());
214	
215	  auto btInteractive = make_unique<DefaultBtInteractive>(
216	      requestGroup_->getDownloadContext(), getPeer());
217	  btInteractive->setBtRuntime(btRuntime_);
218	  btInteractive->setPieceStorage(pieceStorage_);
219	  btInteractive->setPeerStorage(peerStorage); // Note: Not a member variable.
220	  btInteractive->setCuid(cuid);
221	  btInteractive->setBtMessageReceiver(std::move(receiver));
222	  btInteractive->setDispatcher(std::move(dispatcher));
223	  btInteractive->setBtRequestFactory(std::move(reqFactory));
224	  btInteractive->setPeerConnection(std::move(peerConnection));
225	  btInteractive->setExtensionMessageFactory(std::move(extensionMessageFactory));
226	  btInteractive->setExtensionMessageRegistry(std::move(exMsgRegistry));
227	  btInteractive->setKeepAliveInterval(
228	      std::chrono::seconds(getOption()->getAsInt(PREF_BT_KEEP_ALIVE_INTERVAL)));
229	  btInteractive->setRequestGroupMan(
230	      getDownloadEngine()->getRequestGroupMan().get());
231	  btInteractive->setBtMessageFactory(std::move(factory));
232	  if ((metadataGetMode || !torrentAttrs->privateTorrent) &&
233	      !getPeer()->isLocalPeer()) {
234	    if (getOption()->getAsBool(PREF_ENABLE_PEER_EXCHANGE)) {
235	      btInteractive->setUTPexEnabled(true);
236	    }
237	    if (family == AF_INET) {
238	      if (DHTRegistry::isInitialized()) {
239	        btInteractive->setDHTEnabled(true);
240	        factoryPtr->setDHTEnabled(true);
241	        btInteractive->setLocalNode(DHTRegistry::getData().localNode.get());
242	      }
243	    }
244	    else {
245	      if (DHTRegistry::isInitialized6()) {
246	        btInteractive->setDHTEnabled(true);
247	        factoryPtr->setDHTEnabled(true);
248	        btInteractive->setLocalNode(DHTRegistry::getData6().localNode.get());
249	      }
250	    }
251	  }
252	
253	  if (metadataGetMode) {
254	    auto utMetadataRequestFactory = make_unique<UTMetadataRequestFactory>();
255	    auto utMetadataRequestTracker = make_unique<UTMetadataRequestTracker>();
256	
257	    utMetadataRequestFactory->setCuid(cuid);
258	    utMetadataRequestFactory->setDownloadContext(
259	        requestGroup_->getDownloadContext().get());
260	    utMetadataRequestFactory->setBtMessageDispatcher(dispatcherPtr);
261	    utMetadataRequestFactory->setBtMessageFactory(factoryPtr);
262	    utMetadataRequestFactory->setPeer(getPeer());
263	    utMetadataRequestFactory->setUTMetadataRequestTracker(
264	        utMetadataRequestTracker.get());
265	
266	    extensionMessageFactoryPtr->setUTMetadataRequestTracker(
267	        utMetadataRequestTracker.get());
268	
269	    btInteractive->setUTMetadataRequestFactory(
270	        std::move(utMetadataRequestFactory));
271	    btInteractive->setUTMetadataRequestTracker(
272	        std::move(utMetadataRequestTracker));
273	  }
274	
275	  btInteractive->setTcpPort(e->getBtRegistry()->getTcpPort());
276	  if (metadataGetMode) {
277	    btInteractive->enableMetadataGetMode();
278	  }
279	  btInteractive_ = std::move(btInteractive);
280	
281	  btRuntime_->increaseConnections();
282	  requestGroup_->increaseNumCommand();
283	}
284	
285	PeerInteractionCommand::~PeerInteractionCommand()
286	{
287	  if (getPeer()->getCompletedLength() > 0) {
288	    pieceStorage_->subtractPieceStats(getPeer()->getBitfield(),
289	                                      getPeer()->getBitfieldLength());
290	  }
291	  getPeer()->releaseSessionResource();
292	
293	  requestGroup_->decreaseNumCommand();
294	  btRuntime_->decreaseConnections();
295	}
296	
297	bool PeerInteractionCommand::executeInternal()
298	{
299	  setNoCheck(false);
300	  bool done = false;
301	  while (!done) {
302	    switch (sequence_) {
303	    case INITIATOR_SEND_HANDSHAKE:
304	      if (!getSocket()->isWritable(0)) {
305	        done = true;
306	        break;
307	      }
308	      disableWriteCheckSocket();
309	      setReadCheckSocket(getSocket());
310	      // socket->setBlockingMode();
311	      setTimeout(std::chrono::seconds(getOption()->getAsInt(PREF_BT_TIMEOUT)));
312	      btInteractive_->initiateHandshake();
313	      sequence_ = INITIATOR_WAIT_HANDSHAKE;
314	      break;
315	    case INITIATOR_WAIT_HANDSHAKE: {
316	      if (btInteractive_->countPendingMessage() > 0) {
317	        btInteractive_->sendPendingMessage();
318	        if (btInteractive_->countPendingMessage() > 0) {
319	          done = true;
320	          break;
321	        }
322	      }
323	      auto handshakeMessage = btInteractive_->receiveHandshake();
324	      if (!handshakeMessage) {
325	        done = true;
326	        break;
327	      }
328	      btInteractive_->doPostHandshakeProcessing();
329	      sequence_ = WIRED;
330	      break;
331	    }
332	    case RECEIVER_WAIT_HANDSHAKE: {
333	      auto handshakeMessage = btInteractive_->receiveAndSendHandshake();
334	      if (!handshakeMessage) {
335	        done = true;
336	        break;
337	      }
338	      btInteractive_->doPostHandshakeProcessing();
339	      sequence_ = WIRED;
340	      break;
341	    }
342	    case WIRED:
343	      btInteractive_->doInteractionProcessing();
344	      if (btInteractive_->countReceivedMessageInIteration() > 0) {
345	        updateKeepAlive();
346	      }
347	
348	      if (getDownloadEngine()
349	              ->getRequestGroupMan()
350	              ->doesOverallDownloadSpeedExceed() ||
351	          requestGroup_->doesDownloadSpeedExceed()) {
352	        disableReadCheckSocket();
353	        setNoCheck(true);
354	      }
355	      else {
356	        setReadCheckSocket(getSocket());
357	      }
358	
359	      done = true;
360	      break;
361	    }
362	  }
363	  if ((btInteractive_->countPendingMessage() > 0 ||
364	       btInteractive_->isSendingMessageInProgress()) &&
365	      !getDownloadEngine()
366	           ->getRequestGroupMan()
367	           ->doesOverallUploadSpeedExceed() &&
368	      !requestGroup_->doesUploadSpeedExceed()) {
369	    setWriteCheckSocket(getSocket());
370	  }
371	  else {
372	    disableWriteCheckSocket();
373	  }
374	
375	  addCommandSelf();
376	  return false;
377	}
