379	// TODO this method removed when PeerBalancerCommand is implemented
380	bool PeerInteractionCommand::prepareForNextPeer(time_t wait)
381	{
382	  if (peerStorage_->isPeerAvailable() && btRuntime_->lessThanEqMinPeers()) {
383	    cuid_t ncuid = getDownloadEngine()->newCUID();
384	    std::shared_ptr<Peer> peer = peerStorage_->checkoutPeer(ncuid);
385	    // sanity check
386	    if (peer) {
387	      auto command = make_unique<PeerInitiateConnectionCommand>(
388	          ncuid, requestGroup_, peer, getDownloadEngine(), btRuntime_);
389	      command->setPeerStorage(peerStorage_);
390	      command->setPieceStorage(pieceStorage_);
391	      getDownloadEngine()->addCommand(std::move(command));
392	    }
393	  }
394	  return true;
395	}
396	
397	void PeerInteractionCommand::onAbort()
398	{
399	  btInteractive_->cancelAllPiece();
400	  peerStorage_->returnPeer(getPeer());
401	}
402	
403	void PeerInteractionCommand::onFailure(const Exception& err)
404	{
405	  requestGroup_->setLastErrorCode(err.getErrorCode(), err.what());
406	  requestGroup_->setHaltRequested(true);
407	  getDownloadEngine()->setRefreshInterval(std::chrono::milliseconds(0));
408	}
409	
410	bool PeerInteractionCommand::exitBeforeExecute()
411	{
412	  return btRuntime_->isHalt();
413	}
414	
415	const std::shared_ptr<Option>& PeerInteractionCommand::getOption() const
416	{
417	  return requestGroup_->getOption();
418	}
